export const dictionaries = { en, tr } as const;
export type Locale = keyof typeof dictionaries;

export function translate(locale: Locale, key: TranslationKey, values?: Record<string, string | number>) {
  const template = dictionaries[locale][key] ?? en[key];
  if (!values) return template;
  return Object.entries(values).reduce(
    (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
    template as string
  );
}

export function isLocale(value: unknown): value is Locale {
  return value === "tr" || value === "en";
}

export function localizeAgeLabel(value: string, locale: Locale) {
  if (locale !== "tr") return value;
  if (value === "N/A") return "Yok";
  return value
    .replace(/(\d+)\s*d\b/g, "$1g")
    .replace(/(\d+)\s*h\b/g, "$1sa")
    .replace(/(\d+)\s*m\b/g, "$1dk");
}
